update cultivars set origins = $b$[{"author":{"isAI":false,"name":"User"},"body":"インドネシア・ボゴールの Haji Ulih（ハジ・ウリ）が作出し、命名したオリジナル個体（クローン）の名前。オリジナルから代々実生をして改良が続けられており、流通している株はオリジナルの実生（F個体）であって本クローンそのものではない。","body_en":"'King of Spades' is the name of the original individual (a clone) bred and named by Haji Ulih in Bogor, Indonesia. Seedlings of the original have been raised for generations; plants in circulation are those seedlings (F generations), not the clone itself.","discoverer_or_breeder":"Haji Ulih","discovery_year":null,"first_description":null,"native_region":null,"parentage":null,"source_language":"ja","source_name":"","source_tier":"D","source_tier_label_en":"Unknown / Unverified","source_tier_label_jp":"不明・未検証","source_type":"manual","source_url":"","sources":[],"structured":{"citation_links":[],"collector":null,"namer":"Haji Ulih","naming_year":null,"notes":"'King of Spades' はオリジナル個体（クローン）の名前。流通株はオリジナルの実生（F個体）であり、本クローンそのものではない。","origin_type":"clone"},"trust":23,"trustClass":"trust--low","verified":false,"votes":{"agree":0,"disagree":0}}]$b$::jsonb, selected_from_id = null, tags = $b${line}$b$ where id = 2;
